using System.Threading.RateLimiting;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.IdentityModel.Tokens;
using System.Text;

var builder = WebApplication.CreateBuilder(args);

// ---------- JWT Authentication ----------
var jwtSection = builder.Configuration.GetSection("Jwt");
var keyBytes = Encoding.UTF8.GetBytes(
    jwtSection["Key"] ?? throw new InvalidOperationException("Jwt:Key is missing"));

builder.Services
    .AddAuthentication(options =>
    {
        options.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
        options.DefaultChallengeScheme    = JwtBearerDefaults.AuthenticationScheme;
    })
    .AddJwtBearer(options =>
    {
        options.TokenValidationParameters = new TokenValidationParameters
        {
            ValidateIssuer           = true,
            ValidateAudience         = true,
            ValidateLifetime         = true,
            ValidateIssuerSigningKey = true,
            ClockSkew                = TimeSpan.Zero,
            ValidIssuer              = jwtSection["Issuer"],
            ValidAudience            = jwtSection["Audience"],
            IssuerSigningKey         = new SymmetricSecurityKey(keyBytes)
        };
    });

builder.Services.AddAuthorization();

// ---------- CORS ----------
var allowedOrigins = builder.Configuration
    .GetSection("Cors:AllowedOrigins")
    .Get<string[]>() ?? [];

builder.Services.AddCors(options =>
{
    options.AddPolicy("SpaPolicy", policy =>
    {
        policy.WithOrigins(allowedOrigins)
              .AllowAnyHeader()
              .AllowAnyMethod()
              .AllowCredentials();          // needed if the SPA sends cookies / auth headers
    });
});

// ---------- Rate Limiting ----------
builder.Services.AddRateLimiter(options =>
{
    // Return 429 instead of default 503
    options.RejectionStatusCode = StatusCodes.Status429TooManyRequests;

    // Global fixed-window policy
    options.AddFixedWindowLimiter("fixed", limiter =>
    {
        limiter.PermitLimit  = 60;           // max requests per window
        limiter.Window       = TimeSpan.FromMinutes(1);
        limiter.QueueLimit   = 0;            // reject immediately when full
    });

    // Per-user policy keyed on authenticated user id (falls back to IP)
    options.AddPolicy("per-user", context =>
    {
        var key = context.User?.Identity?.IsAuthenticated == true
            ? context.User.FindFirst("sub")?.Value ?? context.User.Identity.Name ?? "anonymous"
            : context.Connection.RemoteIpAddress?.ToString() ?? "unknown";

        return RateLimitPartition.GetFixedWindowLimiter(key, _ =>
            new FixedWindowRateLimiterOptions
            {
                PermitLimit = 30,
                Window      = TimeSpan.FromMinutes(1),
                QueueLimit  = 0
            });
    });
});

builder.Services.AddControllers();

var app = builder.Build();

// Order matters: CORS → Rate Limiting → Auth → Controllers
app.UseHttpsRedirection();
app.UseCors("SpaPolicy");
app.UseRateLimiter();
app.UseAuthentication();
app.UseAuthorization();

app.MapControllers()
   .RequireRateLimiting("per-user");       // apply per-user limit to all endpoints

app.Run();

